//! Engine — 量子円柱。単一ファイル。全コンポーネントが1つのmmapを共有。
//!
//!   entity() → ID 振る
//!   tie_text → 文字列を紐で張る（Vocabulary 経由）
//!   tie     → u32 値を紐で張る
//!   untie → 紐を外す
//!   content/get_content → 非索引テキスト
//!   query → 円柱の重なりを一発で返す
//!   delete → entity 削除
//!   commit → WAL Commit marker append (WAL 有効時のみ意味あり)
//!   open/flush → 永続化（mmap なので open は即利用可）

#[cfg(not(target_arch = "wasm32"))]
use std::fs::OpenOptions;
use std::io;

#[cfg(not(target_arch = "wasm32"))]
use crate::segments::{SegmentKind, SegmentSet, SegmentSizes};
#[cfg(not(target_arch = "wasm32"))]
use std::sync::Arc;

// std::time::Instant panics on wasm32-unknown-unknown ("time not implemented").
// load_from_backing's [open_profile] timer is on the wasm read path, so alias
// Instant to the web-time shim there.
#[cfg(not(target_arch = "wasm32"))]
use std::time::Instant;
#[cfg(target_arch = "wasm32")]
use web_time::Instant;

use crate::region::Region;

/// get_entity の戻り値。
#[derive(Debug, PartialEq)]
pub enum EntityValue<'a> {
    Num(u32),
    /// 64 bit 列 (`ValueType::Number64`) の値。
    Num64(u64),
    Text(&'a [u8]),
    Content(&'a [u8]),
}

/// `get_entity_owned` の戻り値。 [`EntityValue`] の text を copy して持つ版 (#107)。
#[derive(Debug, Clone, PartialEq)]
pub enum EntityValueOwned {
    Num(u32),
    /// 64 bit 列 (`ValueType::Number64`) の値。
    Num64(u64),
    Text(Vec<u8>),
}

/// table の eid 枠の使用状況。 `Engine::table_eid_usage` の戻り値。
///
/// 数えるのは**今ある枠**だけ。 枠を使い切ると `entity_in` は、 どの table にも割り当てていない eid 空間
/// ([`Engine::remaining_eid_capacity`]) から枠を足す (v10 Phase 3)。 なので `free == 0` は 「次の `entity_in` が
/// 枠を足す」 であって、 満杯ではない (#364)。 満杯 = `entity_in` が `Err` を返すのは、
/// `remaining_eid_capacity() == 0` かつ `free == 0` の時。 書き手が動いている間に見るなら、 この順に見る:
/// 残りは [`Engine::grow_entity_cap`] を呼ばない限り減るだけなので、 0 を見た後は枠が伸びない (逆の順だと、
/// 2 つの読みの間に枠が足されて満杯に見える)。
///
/// 例外は `_sync_ops` (sync の未配送 record の ring): 自動では枠を足さないので、 `free == 0` が満杯 (#368)。
///
/// 満杯になると **アプリの掃引がそこで止まる** — 掃引が止まると削除も流れなくなり、 削除は枠を空ける手段なので
/// 抜け出しにくい (他の手段は [`Engine::grow_entity_cap`])。 その手前で気付けるように、 残量を問い合わせられる。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TableEidUsage {
    /// 今ある枠の総数 (全 extent の合計)。 枠を足すと増える。
    pub capacity: u32,
    /// これまでに払い出した最大 (= `next_local`)。 削除で空いた分は含んだまま。
    pub allocated: u32,
    /// いま生きている行数。
    pub live: u32,
    /// 今ある枠にあと何行入るか (= `capacity - live`)。 削除で空いた slot は
    /// `entity_in` が free list 経由で再利用するのでここに戻る。 0 でも、 空き eid 空間が
    /// 残っていれば次の `entity_in` で枠が足される。
    pub free: u32,
}

/// changefeed の cursor と、 畳んだ ring から移した、 まだ listener に渡していない record。
struct ChangeCursor {
    /// 次に listener へ渡す WAL offset。 add_change_listener 時に wal.head() に合わせ、 それ以降の commit だけが流れる。
    offset: u64,
    /// 畳む時に ring から移した、 Commit で閉じた record (古い順)。 次の配信が ring の分より先に渡す。
    committed: Vec<crate::transport::WireRecord>,
    /// 畳む時に Commit で閉じていなかった末尾の record。 その group が閉じたら (cursor の先に Commit が来たら)、 頭として渡す。
    open_tail: Vec<crate::transport::WireRecord>,
    /// #560: `committed` と `open_tail` の大きさの見積もり (byte、 [`change_record_bytes`])。 上限を越えたら溜めを捨てて
    /// listener を外す。
    bytes: usize,
    /// #560: 溜めの上限を越えて外した listener (通知係が `on_detached` を呼ぶまで置く) と、 渡せなかった最初の record の HLC。
    detached: Vec<std::sync::Arc<dyn crate::changefeed::ChangeListener>>,
    lost_from: Option<enchudb_oplog::Hlc>,
    /// 記録 (`changefeed.seg`) の無い時に渡した record の数 (process の中だけの番号、 `on_changes_at` に渡す)。
    seq: u64,
    /// 記録がある時: 記録に写し終えた WAL の offset。
    log_wal: u64,
    /// 記録がある時の listener ごとの位置 (次に渡す記録の番号)。
    readers: Vec<(std::sync::Arc<dyn crate::changefeed::ChangeListener>, u64)>,
    /// 記録が位置を越えて捨てたので外した listener と、 渡せなかった最初の record の HLC (通知係が `on_detached` を呼ぶ)。
    log_detached: Vec<(std::sync::Arc<dyn crate::changefeed::ChangeListener>, enchudb_oplog::Hlc)>,
}

/// #560: 溜めの既定の上限 (byte)。 `Engine::set_change_backlog_limit` で変える。
pub const DEFAULT_CHANGE_BACKLOG_LIMIT: usize = 64 << 20;

/// 差分の記録 (`LiveQuery::poll_since` / `LiveCounts::poll_since`) の 1 購読あたりの既定の上限 (byte)。
/// `Engine::set_answer_log_limit` で変える。
pub const DEFAULT_ANSWER_LOG_LIMIT: usize = 16 << 20;

/// #560: 溜めの 1 record の大きさの見積もり (構造体 + 署名した bytes)。
fn change_record_bytes(r: &crate::transport::WireRecord) -> usize {
    std::mem::size_of::<crate::transport::WireRecord>() + r.signed_bytes.len()
}

/// [`Engine::verify_invariants`] の答え。 `violations` が空なら不変量は全部成り立つ。 `warnings` は 「今の code では
/// まだ約束していないが、 約束するつもりの形」 (主キーの重複、 #601 が直るまで)
#[derive(Debug, Default, Clone)]
pub struct Invariants {
    pub violations: Vec<String>,
    pub warnings: Vec<String>,
}

impl Invariants {
    pub fn ok(&self) -> bool {
        self.violations.is_empty()
    }
}

/// Engine の実行時状態スナップショット。
#[derive(Debug, Clone)]
pub struct EngineStats {
    pub entity_count: u32,
    pub himo_count: u32,
    /// WAL の次 append 位置(byte offset)
    pub oplog_head: u64,
    /// 本体へ反映 + fsync 済みの位置
    pub oplog_checkpoint: u64,
    /// WAL ファイル容量(設定値、sparse)
    pub oplog_capacity: u64,
    /// head - checkpoint。大きいと未 fsync が溜まっている
    pub oplog_lag_bytes: u64,
    /// 発行済みの最大 LSN
    pub oplog_next_lsn: u64,
    /// fsync/msync 完了済みの LSN(背景 fsync が進めた地点)
    pub durable_lsn: u64,
    /// 0.33 までの write queue に滞留中の op 数。 0.34 で queue を外したので常に 0 (互換のために残す)
    pub queue_len: usize,
    /// 0.33 までの write queue に writer が push した累計。 0.34 から常に 0 (同上)
    pub pushed: u64,
    /// 0.33 までの consumer が apply した累計。 0.34 から常に 0 (同上)
    pub applied: u64,
    /// 自 peer の peer_id(単独 peer 運用では 0)
    pub peer_id: u32,
    /// **pre-v9 DB の**揮発版数置き場のエントリ数。 v9 DB では版数が
    /// per-cell version column に載るので常に 0 (走査が O(entity × himo) に
    /// なるため column 側の集計は取らない)。
    pub hlc_entries: usize,
    /// 同上 — pre-v9 DB の揮発置き場の最大 HLC。 v9 DB では None。
    pub max_hlc: Option<enchudb_oplog::Hlc>,
    /// #178: 「自分が書いた行が後から foreign identity に束ねられた」 累計。
    /// `> 0` なら相手側に PK 無しの重複行が生えている可能性がある。 0 が常態。
    pub bind_over_local_writes: u64,
}

/// 0.8.16 (issue #54): vocab の orphan (= 死蔵 vid) 検出スナップショット。
/// `ValueType::Leaf` の値は `vocab.insert` (常に新 vid 払出) で書かれるため、
/// re-tie / remove で旧 vid が himo から外れても vocab data 側は残置する。
/// 同 vid を参照する live cell が皆無の vid を orphan として計上する。
///
/// 計測は read-only で、 vocab 自体は変更しない。 `Tag` himo (= `get_or_insert`
/// 経由で dedup) も live set の collection 対象 (= ある vid を Tag が参照中なら
/// Leaf が後から orphan にしても live 判定)。
/// **capacity 到達・edge 値・破損 file のような 「想定内だが続行不能」 な事象** (#59)。
///
/// embedded DB は他人の process に埋め込まれる。 「DB が一杯」 「値が範囲外」 で
/// `panic!` すると host app ごと落ちるし、 FFI 境界を unwind すれば未定義動作になる。
/// そこで engine 内部ではこれらを panic にせず、
///
/// 1. その write を **拒否** し (壊れた値を書かない)
/// 2. 種別ごとに **計数** し (`Engine::fault_count`)
/// 3. **rate-limited に warn** する (黙って落とさない)
///
/// という扱いに統一する。 `Result` を返せる API では併せて `Err` を返す。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FaultKind {
    /// entity 枠が満杯 (max_entities 到達 + free stack 空)
    EntitySpace,
    /// content data 領域が満杯 (既定 512 MB)
    ContentSpace,
    /// vocabulary が満杯 (vocab_max_entries 到達)
    VocabSpace,
    /// 値が cell に入らない (`u32::MAX` は sentinel 予約)
    ValueOutOfRange,
    /// #167: filesystem の空き容量不足で DB を伸ばせない
    DiskSpace,
    /// #381: Tag の値の番号が古い (語が回収されて番号の場所が別の語に渡った)。 古い番号で書こうとした
    StaleValue,
    /// #534: 列の segment を初めて開く I/O が失敗した (一時的な EIO / mmap の失敗など)。 書き込みは何も変えずに断り、
    /// 次に触った時にまた開いてみる
    SegmentIo,
    /// #553 / #554: 書き込みが WAL に載らない (WAL より大きい record、 または sync の表の無い DB で満杯の WAL を畳めない)。
    /// 本体にも当てずに断る
    WalSpace,
}

impl FaultKind {
    pub(crate) const COUNT: usize = 8;
    pub(crate) fn index(self) -> usize {
        match self {
            FaultKind::EntitySpace => 0,
            FaultKind::ContentSpace => 1,
            FaultKind::VocabSpace => 2,
            FaultKind::ValueOutOfRange => 3,
            FaultKind::DiskSpace => 4,
            FaultKind::StaleValue => 5,
            FaultKind::SegmentIo => 6,
            FaultKind::WalSpace => 7,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            FaultKind::EntitySpace => "entity space exhausted",
            FaultKind::ContentSpace => "content space exhausted",
            FaultKind::VocabSpace => "vocabulary full",
            FaultKind::ValueOutOfRange => "value out of range",
            FaultKind::DiskSpace => "filesystem is (nearly) full",
            FaultKind::StaleValue => "stale value id (reclaimed)",
            FaultKind::SegmentIo => "column segment could not be opened",
            FaultKind::WalSpace => "the write does not fit in the oplog (WAL)",
        }
    }
}

/// `try_tie_*_to_by_id` が書かなかった理由 (#316)。 書かなかった時は oplog にも積まない。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TieRejected {
    /// 容量 / 値の範囲 (`Engine::fault_count` にも積まれる)
    Fault(FaultKind),
    /// cell に今より新しい版数が在る (時計が戻った、 LWW で負けた)
    OlderThanCell,
}

impl std::fmt::Display for TieRejected {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TieRejected::Fault(k) => f.write_str(k.as_str()),
            TieRejected::OlderThanCell => f.write_str("the cell has a newer version (clock went backwards?)"),
        }
    }
}

impl std::error::Error for TieRejected {}

/// #513: 削除の道で積む、 消した主キーの行 (`Engine::pk_pending`)。 値は local な値 (Tag は辞書の番号。 辞書を回収する DB
/// の文字列の主キーは積まずにその場で載せるので、 番号は載せる時まで同じ文字列を指す)。
#[derive(Debug, Clone, Copy)]
struct PkPending {
    slot: u32,
    himo: u16,
    value: u64,
    hlc: enchudb_oplog::Hlc,
}

/// #513: 覚えた主キーの bit の表の大きさ (bit、 2 の冪)。 64 KiB。
const PK_BLOOM_BITS: usize = 1 << 19;

/// #513: 主キーの bit の表の番地 (FNV-1a 64)。
fn pk_bloom_index(himo: u16, key: &[u8]) -> usize {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in himo.to_le_bytes().iter().chain(key) {
        h ^= b as u64;
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    (h as usize) & (PK_BLOOM_BITS - 1)
}

/// #513: 主キーで束ねる時の主キーの値 ([`Engine::reserve_remote_eid_for_pk`])。 受け手の辞書にある値・数などは local な
/// 値 (`Local`)、 受け手の辞書に無い文字列 (届いた `Vocab` の bytes) は `Text`。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PkValue<'a> {
    Local(u64),
    Text(&'a [u8]),
}


/// `remote_*_apply` (sync 受信の apply) の結果 (#210)。
///
/// 旧 `bool` は 「適用した / しなかった」 しか区別できず、 **「LWW で古い」 と
/// 「容量が無くて置けなかった」 が同じ `false` に潰れていた**。 sync 側はそれを
/// `SkippedOlder` (= 再配送不要) として計上するため、 **ディスク満杯や content
/// 天井に当たった record は cursor を越えられて恒久的に失われる**。
///
/// 前者は再配送しても結果が変わらないが、 後者は **空きが出てから再配送しないと
/// 埋まらない**。 cursor を進めてよいかの判断が真逆なので型で分ける
/// (`SyncOutcome::skipped` と `dropped_unresolved` を分けたのと同じ理由)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RemoteApply {
    /// 適用した。
    Applied,
    /// **LWW で古い** / 既に適用済み / tombstone に負けた / 宛先の himo が無い。
    /// 再配送しても結果は変わらない。
    Stale,
    /// **容量が足りず置けなかった** (`FaultKind::DiskSpace` / `ContentSpace`)。
    /// 値は一切書いていない。 **空きが出てからの再配送が必要**。
    RejectedCapacity,
}

impl RemoteApply {
    /// 適用されたか。
    pub fn applied(self) -> bool {
        matches!(self, RemoteApply::Applied)
    }

    /// 再配送が必要か (= cursor をこの record より先に進めてはいけない)。
    pub fn needs_redelivery(self) -> bool {
        matches!(self, RemoteApply::RejectedCapacity)
    }
}

/// 辞書 (Tag の値の共有辞書) の使用量と上限 (#381)。 `Engine::vocab_usage` が O(1) で返す。
///
/// 語を回収しない DB では、 語は行を消しても戻らないので、 `entries` はこれまでに入れた値の種類の総数。 上限に着くと
/// DB の**全ての表**で新しい Tag の値が書けなくなる (`FaultKind::VocabSpace`)。 残りを見て `Engine::grow_vocab` で
/// 伸ばすか、 語を回収する (`Engine::enable_vocab_reclaim`、 #381)。 回収する DB では `entries` は使った場所の数で、
/// 空いた場所は `reclaimable_entries`。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VocabUsage {
    /// 辞書の語数 (行から参照されなくなった語も含む)。
    pub entries: u32,
    /// 語数の上限 (header の `vocab_max_entries`)。
    pub max_entries: u32,
    /// data の使用 byte 数 (先頭 16 B の header を含む)。
    pub data_bytes: u64,
    /// data の上限 byte 数 (header の `vocab_data_size`)。
    pub max_data_bytes: u64,
    /// 開いたまま `grow_vocab` で伸ばせる語数の上限 (予約)。 開いた時の上限の 4 倍以上 (64 KiB 単位で切り上げる)。
    /// 開き直すと伸ばした上限の 4 倍以上になる。
    pub reserved_entries: u32,
    /// 開いたまま `grow_vocab` で伸ばせる data の byte 数の上限 (予約)。
    pub reserved_data_bytes: u64,
    /// 語を回収する DB として開いたか (`enable_vocab_reclaim` / `GrowableOptions::vocab_reclaim`)。
    pub reclaim: bool,
    /// 回収が始まったか (開いた時に始まる、 #385)。
    pub reclaim_ready: bool,
    /// 行から参照されなくなり、 使い回しを待っている語の数 (多めに数えることがある — 使い回す前に参照 0 を確かめる)。
    /// `max_entries - entries + reclaimable_entries` が新しく入れられる値の数の目安。
    pub reclaimable_entries: u32,
    /// この session で番号を使い回した回数。
    pub reclaimed: u64,
}

#[derive(Debug, Clone)]
pub struct VocabOrphanStats {
    /// vocab に発行済みの全 vid 数 (= `Vocabulary::count()`)。
    pub vocab_total: u32,
    /// いずれかの himo cell から参照されている vid 数。
    pub live_vids: u32,
    /// `vocab_total - live_vids`。 死蔵の vid 数。
    pub orphan_vids: u32,
    /// orphan vid に対応する vocab data の総 byte 数 (= 救出可能領域)。
    pub orphan_bytes: u64,
    /// live vid に対応する vocab data の総 byte 数 (= 健全に使われてる領域)。
    pub live_bytes: u64,
}

impl VocabOrphanStats {
    /// `orphan_vids / vocab_total` の比率 (`vocab_total == 0` なら 0.0)。
    pub fn dead_ratio(&self) -> f64 {
        if self.vocab_total == 0 { 0.0 }
        else { self.orphan_vids as f64 / self.vocab_total as f64 }
    }
}

/// #88 (0.12.0): v5 (leaf region 無し = Leaf を vocab に格納) DB を v6
/// (LeafStore あり) へ移送した結果。 `Engine::migrate_bytes_v5_to_v6` 等が返す。
#[derive(Debug, Clone, Default)]
pub struct MigrationStats {
    /// 入力が既に v6 (leaf region あり) で移送不要だった。 他フィールドは 0。
    pub already_v6: bool,
    /// 移送対象になった Leaf himo 数。
    pub leaf_himos: u32,
    /// vocab → LeafStore に移した cell (= Leaf 値) の数。
    pub cells_moved: u64,
    /// 移した payload の総 byte 数 (slot header / padding は含まない生 bytes)。
    pub bytes_moved: u64,
    /// 移送後の LeafStore footprint (high_water、 byte)。
    pub leaf_footprint: u64,
    /// 移送後も vocab data に残る旧 Leaf bytes (= 死蔵)。 本 migration は
    /// vocab compaction をしないので、 この分は footprint に残る (既知の trade-off)。
    pub vocab_orphan_bytes_left: u64,
}

fn oplog_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::OPLOG)
}

/// β-light step 7: table 定義 metadata の sidecar path (v10: `{db}/tables`)。
/// 中身は binary encoded `TableDef` 配列、 atomic 書き換え (`tables.tmp` →
/// rename) で更新。 不在なら open 時は anonymous fallback。
#[cfg(not(target_arch = "wasm32"))]
fn tables_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::TABLES)
}

/// β-light step 7: tables Vec を binary encode。
///
/// layout:
///   magic: "TBL1" (4)
///   version: u32 = 1
///   table_count: u32
///   per table:
///     name_len: u32
///     name: u8[name_len]
///     eid_range_lo: u32
///     eid_range_hi: u32
///     next_local: u32
///     himo_count: u32
///     himo_ids: u32[himo_count]
///     fk_count: u32
///     fk_refs: [(u32 himo_id, u32 (target_table as u32))] × fk_count
///
/// #141 の PK は **全 table を書き切った後ろに optional block** として足す
/// (version は 1 のまま):
///   pk_magic: "PKS1" (4)
///   pk_count: u32
///   [(table_index: u32, pk_himo: u32)] × pk_count
///
/// version を上げずに末尾追記にしているのは **前方互換のため**。 table loop は
/// `table_count` 回で終わって残りを読まないので、 #141 以前のバイナリはこの block を
/// 単に無視して従来どおり開ける (PK 情報が落ちるだけ = PK-aware apply が効かなくなる
/// だけで、 DB が開けなくなることはない)。 version を 2 に上げると古いバイナリが
/// `unsupported version` で **開けなくなる** ため、 同じ DB を旧 enchudb で開く別
/// プロセスを巻き込む。
///
/// 並びの索引の宣言 (`orders`、 [`Engine::declare_order`]) は `DIA1` block として一番後ろに足す (`PKS1` / `EXT1` を
/// 知っている古いバイナリは、 それを読んでから知らない magic の所で止まる)。
fn serialize_tables(tables: &[TableDef], orders: &[OrderDecl], marks: &[u16], answers: &[AnswerDecl]) -> Vec<u8> {
    let mut out = Vec::with_capacity(64 + tables.len() * 128);
    out.extend_from_slice(b"TBL1");
    out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&(tables.len() as u32).to_le_bytes());
    for t in tables {
        let name_bytes = t.name.as_bytes();
        out.extend_from_slice(&(name_bytes.len() as u32).to_le_bytes());
        out.extend_from_slice(name_bytes);
        out.extend_from_slice(&t.eid_range_lo.to_le_bytes());
        out.extend_from_slice(&t.eid_range_hi.to_le_bytes());
        out.extend_from_slice(&t.next_local.load(std::sync::atomic::Ordering::Relaxed).to_le_bytes());
        let himo_ids = t.himo_ids.read().unwrap();
        out.extend_from_slice(&(himo_ids.len() as u32).to_le_bytes());
        for &h in himo_ids.iter() {
            out.extend_from_slice(&h.to_le_bytes());
        }
        drop(himo_ids);
        out.extend_from_slice(&(t.fk_refs.len() as u32).to_le_bytes());
        for &(hid, tid) in &t.fk_refs {
            out.extend_from_slice(&hid.to_le_bytes());
            out.extend_from_slice(&(tid as u32).to_le_bytes());
        }
    }
    // #141: PK block (optional trailer)。 PK を 1 つも持たないなら書かない
    // (= #141 以前と 1 byte も変わらない出力)。
    let pks: Vec<(u32, u32)> = tables
        .iter()
        .enumerate()
        .filter_map(|(i, t)| t.pk_himo.map(|h| (i as u32, h as u32)))
        .collect();
    if !pks.is_empty() {
        out.extend_from_slice(b"PKS1");
        out.extend_from_slice(&(pks.len() as u32).to_le_bytes());
        for (idx, hid) in pks {
            out.extend_from_slice(&idx.to_le_bytes());
            out.extend_from_slice(&hid.to_le_bytes());
        }
    }
    // v10 Phase 3 (request20 案 B): 追加 extent。 PKS1 と同じ末尾 optional block (version 据え置き)。
    //   ext_magic: "EXT1" (4)
    //   ext_count: u32                         (extent を持つ table の数)
    //   [(table_index: u32, n: u32, [(lo: u32, hi: u32)] × n)] × ext_count
    let ext: Vec<(u32, Vec<(u32, u32)>)> = tables
        .iter()
        .enumerate()
        .filter_map(|(i, t)| {
            let e = t.extra.read().unwrap();
            if e.is_empty() { None } else { Some((i as u32, e.clone())) }
        })
        .collect();
    if !ext.is_empty() {
        out.extend_from_slice(b"EXT1");
        out.extend_from_slice(&(ext.len() as u32).to_le_bytes());
        for (idx, extents) in ext {
            out.extend_from_slice(&idx.to_le_bytes());
            out.extend_from_slice(&(extents.len() as u32).to_le_bytes());
            for (lo, hi) in extents {
                out.extend_from_slice(&lo.to_le_bytes());
                out.extend_from_slice(&hi.to_le_bytes());
            }
        }
    }
    // 並びの索引の宣言。 EXT1 の後ろ (古いバイナリが PKS1 / EXT1 を読み終えてから止まるように)。 宣言が無ければ書かない
    // (= 宣言の無い DB は 1 byte も変わらない)。
    //   dia_magic: "DIA1" (4)
    //   dia_count: u32
    //   [(via: u32, key: u32, n: u32, [tick: u64] × n)] × dia_count
    if !orders.is_empty() {
        out.extend_from_slice(b"DIA1");
        out.extend_from_slice(&(orders.len() as u32).to_le_bytes());
        for (via, key, ticks) in orders {
            out.extend_from_slice(&u32::from(*via).to_le_bytes());
            out.extend_from_slice(&u32::from(*key).to_le_bytes());
            out.extend_from_slice(&(ticks.len() as u32).to_le_bytes());
            for t in ticks {
                out.extend_from_slice(&t.to_le_bytes());
            }
        }
    }
    // 位置の印の宣言 ([`Engine::declare_marks`])。 DIA1 の後ろ。 宣言が無ければ書かない。
    //   mrk_magic: "MRK1" (4)
    //   mrk_count: u32
    //   [himo: u32] × mrk_count
    if !marks.is_empty() {
        out.extend_from_slice(b"MRK1");
        out.extend_from_slice(&(marks.len() as u32).to_le_bytes());
        for h in marks {
            out.extend_from_slice(&u32::from(*h).to_le_bytes());
        }
    }
    // 宣言された答え ([`Engine::declare_answer`])。 MRK1 の後ろ。 宣言が無ければ書かない。
    //   ans_magic: "ANS1" (4)
    //   ans_count: u32
    //   [(name_len: u32, name (UTF-8), 形 (`AnswerSpec::encode`: 種類 u8 + 中身))] × ans_count
    if !answers.is_empty() {
        out.extend_from_slice(b"ANS1");
        out.extend_from_slice(&(answers.len() as u32).to_le_bytes());
        for (name, spec) in answers {
            out.extend_from_slice(&(name.len() as u32).to_le_bytes());
            out.extend_from_slice(name.as_bytes());
            spec.encode(&mut out);
        }
    }
    out
}

/// 並びの索引の宣言 1 つ: (via の紐, key の紐, 目盛り)。
type OrderDecl = (u16, u16, Vec<u64>);
/// 宣言された答え 1 つ: (名前, 形)。
type AnswerDecl = (String, crate::live::AnswerSpec);
/// `{db}/tables` の中身: (table 定義, 並びの索引の宣言, 位置の印を持つ紐, 宣言された答え)。
type TablesSidecar = (Vec<TableDef>, Vec<OrderDecl>, Vec<u16>, Vec<AnswerDecl>);

/// `ANS1` block の中身 (magic の後ろ) を読む: (宣言, 読んだ byte 数)。 途中で切れている / 名前が UTF-8 でない / 形が
/// 読めない (`AnswerSpec::decode`) なら None。
fn deserialize_answers(buf: &[u8]) -> Option<(Vec<AnswerDecl>, usize)> {
    let mut off = 0usize;
    let u32_at = |off: &mut usize| -> Option<u32> {
        let v = u32::from_le_bytes(buf.get(*off..*off + 4)?.try_into().ok()?);
        *off += 4;
        Some(v)
    };
    let count = u32_at(&mut off)? as usize;
    // 1 件は最低 10 byte (name_len + 名前 1 byte + 種類 + 条件の数)
    let mut out = Vec::with_capacity(count.min(buf.len() / 10));
    for _ in 0..count {
        let n = u32_at(&mut off)? as usize;
        let name = std::str::from_utf8(buf.get(off..off.checked_add(n)?)?).ok()?.to_string();
        off += n;
        let spec = crate::live::AnswerSpec::decode(buf, &mut off)?;
        out.push((name, spec));
    }
    Some((out, off))
}

/// `MRK1` block の中身 (magic の後ろ) を読む: (位置の印を持つ紐の番号, 読んだ byte 数)。 途中で切れている / 番号が紐の id に
/// 入らないなら None。
fn deserialize_marks(buf: &[u8]) -> Option<(Vec<u16>, usize)> {
    let mut off = 0usize;
    let u32_at = |off: &mut usize| -> Option<u32> {
        let v = u32::from_le_bytes(buf.get(*off..*off + 4)?.try_into().ok()?);
        *off += 4;
        Some(v)
    };
    let count = u32_at(&mut off)? as usize;
    let mut out = Vec::with_capacity(count.min(buf.len() / 4));
    for _ in 0..count {
        out.push(u16::try_from(u32_at(&mut off)?).ok()?);
    }
    Some((out, off))
}

/// `DIA1` block の中身 (magic の後ろ) を読む: (宣言, 読んだ byte 数)。 途中で切れている / 番号が紐の id に入らない
/// なら None。
fn deserialize_orders(buf: &[u8]) -> Option<(Vec<OrderDecl>, usize)> {
    let mut off = 0usize;
    let u32_at = |off: &mut usize| -> Option<u32> {
        let v = u32::from_le_bytes(buf.get(*off..*off + 4)?.try_into().ok()?);
        *off += 4;
        Some(v)
    };
    let count = u32_at(&mut off)? as usize;
    // 1 件は最低 12 byte (via / key / n)。 壊れた count で大きく確保しない
    let mut out = Vec::with_capacity(count.min(buf.len() / 12));
    for _ in 0..count {
        let via = u16::try_from(u32_at(&mut off)?).ok()?;
        let key = u16::try_from(u32_at(&mut off)?).ok()?;
        let n = u32_at(&mut off)? as usize;
        let bytes = buf.get(off..off.checked_add(n.checked_mul(8)?)?)?;
        let ticks = bytes.as_chunks::<8>().0.iter().map(|&c| u64::from_le_bytes(c)).collect();
        off += bytes.len();
        out.push((via, key, ticks));
    }
    Some((out, off))
}

/// β-light step 7: tables sidecar を decode。 magic 不一致 / 短すぎる buffer
/// は Err。 部分破損は次の field 読みで失敗 → Err として扱う。 並びの索引の宣言 (`DIA1`) も返す (無ければ空)。
fn deserialize_tables(buf: &[u8]) -> Result<TablesSidecar, String> {
    if buf.len() < 12 || &buf[0..4] != b"TBL1" {
        return Err("tables sidecar: bad magic".into());
    }
    let version = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    if version != 1 {
        return Err(format!("tables sidecar: unsupported version {}", version));
    }
    let table_count = u32::from_le_bytes(buf[8..12].try_into().unwrap()) as usize;
    // 破損ガード: 巨大 count をそのまま with_capacity に渡すと OOM abort。 各 table は
    // 最低 24 byte (name_len + lo/hi/next/himo_count/fk_count = 6×u32、 name 空) なので
    // 残りバッファで prealloc を cap する (truncation 自体は下の read_u32! が検出する)。
    let mut tables = Vec::with_capacity(table_count.min((buf.len() - 12) / 24));
    let mut off = 12usize;

    macro_rules! read_u32 {
        ($buf:expr, $off:expr) => {{
            if $off + 4 > $buf.len() {
                return Err("tables sidecar: truncated".into());
            }
            let v = u32::from_le_bytes($buf[$off..$off + 4].try_into().unwrap());
            $off += 4;
            v
        }};
    }

    for _ in 0..table_count {
        let name_len = read_u32!(buf, off) as usize;
        if off + name_len > buf.len() {
            return Err("tables sidecar: truncated (name)".into());
        }
        let name = String::from_utf8_lossy(&buf[off..off + name_len]).to_string();
        off += name_len;
        let eid_range_lo = read_u32!(buf, off);
        let eid_range_hi = read_u32!(buf, off);
        let next_local_u32 = read_u32!(buf, off);
        let next_local = std::sync::atomic::AtomicU32::new(next_local_u32);
        let himo_count = read_u32!(buf, off) as usize;
        let mut himo_ids = Vec::with_capacity(himo_count.min((buf.len() - off) / 4));
        for _ in 0..himo_count {
            himo_ids.push(read_u32!(buf, off));
        }
        let fk_count = read_u32!(buf, off) as usize;
        let mut fk_refs = Vec::with_capacity(fk_count.min((buf.len() - off) / 8));
        for _ in 0..fk_count {
            let hid = read_u32!(buf, off);
            let tid = read_u32!(buf, off);
            fk_refs.push((hid, tid as TableId));
        }
        tables.push(TableDef {
            name,
            himo_ids: std::sync::RwLock::new(himo_ids),
            eid_range_lo,
            eid_range_hi,
            fk_refs,
            next_local,
            free_locals: std::sync::Arc::new(std::sync::Mutex::new(Vec::new())),
            free_locals_nonempty: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
            extra: std::sync::RwLock::new(Vec::new()),
            pk_himo: None,
        });
    }

    // #141: optional PK trailer。 無ければ (= #141 以前が書いた sidecar) PK 無しのまま。
    // 壊れた trailer は「PK 情報が無い」扱いにするだけで、 sidecar 全体は有効とする
    // (PK は再 build で復元できる派生情報であって、 table 定義の本体ではない)。
    // 末尾の optional block 群 (順不同、 未知の magic で打ち切り)
    let mut orders = Vec::new();
    let mut marks: Vec<u16> = Vec::new();
    let mut answers: Vec<AnswerDecl> = Vec::new();
    while off + 8 <= buf.len() {
        let magic = &buf[off..off + 4];
        if magic == b"PKS1" {
            off += 4;
            let pk_count = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) as usize;
            off += 4;
            for _ in 0..pk_count {
                if off + 8 > buf.len() {
                    break;
                }
                let idx = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) as usize;
                off += 4;
                let hid = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
                off += 4;
                if let Some(t) = tables.get_mut(idx) {
                    if hid <= u16::MAX as u32 {
                        t.pk_himo = Some(hid as u16);
                    }
                }
            }
        } else if magic == b"EXT1" {
            off += 4;
            let ext_count = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) as usize;
            off += 4;
            for _ in 0..ext_count {
                if off + 8 > buf.len() {
                    return Err("tables sidecar: truncated (EXT1)".into());
                }
                let idx = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) as usize;
                off += 4;
                let n = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) as usize;
                off += 4;
                if off + n.saturating_mul(8) > buf.len() {
                    return Err("tables sidecar: truncated (EXT1 extents)".into());
                }
                let mut extents = Vec::with_capacity(n);
                for _ in 0..n {
                    let lo = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
                    off += 4;
                    let hi = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
                    off += 4;
                    if lo >= hi {
                        return Err(format!("tables sidecar: bad extent [{lo}, {hi})"));
                    }
                    extents.push((lo, hi));
                }
                if let Some(t) = tables.get_mut(idx) {
                    *t.extra.write().unwrap() = extents;
                }
            }
        } else if magic == b"DIA1" {
            // 並びの索引の宣言。 索引は列から作り直せる派生のデータなので、 壊れていたら宣言なしとして読む
            // (sidecar 全体は有効)
            match deserialize_orders(&buf[off + 4..]) {
                Some((decls, used)) => {
                    orders = decls;
                    off += 4 + used;
                }
                None => {
                    eprintln!("warning: tables sidecar: broken order declarations (DIA1), ignored");
                    break;
                }
            }
        } else if magic == b"MRK1" {
            // 位置の印の宣言。 印は列から作り直せる派生のデータなので、 壊れていたら宣言なしとして読む (sidecar 全体は有効)
            match deserialize_marks(&buf[off + 4..]) {
                Some((decls, used)) => {
                    marks = decls;
                    off += 4 + used;
                }
                None => {
                    eprintln!("warning: tables sidecar: broken marks declarations (MRK1), ignored");
                    break;
                }
            }
        } else if magic == b"ANS1" {
            // 宣言された答え。 答えは列から作り直せる派生のデータなので、 壊れていたら宣言なしとして読む (sidecar 全体は有効)
            match deserialize_answers(&buf[off + 4..]) {
                Some((decls, used)) => {
                    answers = decls;
                    off += 4 + used;
                }
                None => {
                    eprintln!("warning: tables sidecar: broken answer declarations (ANS1), ignored");
                    break;
                }
            }
        } else {
            break;
        }
    }
    Ok((tables, orders, marks, answers))
}

/// β-light step 7: tables を sidecar に atomic 書き換え。 fsync まで含む。 `orders` は並びの索引の宣言 (`DIA1`)。
#[cfg(not(target_arch = "wasm32"))]
fn persist_tables_to_sidecar(
    db_path: &str,
    tables: &[TableDef],
    orders: &[OrderDecl],
    marks: &[u16],
    answers: &[AnswerDecl],
) -> io::Result<()> {
    crate::db_files::write_atomic_if_changed(&tables_path_for(db_path), &serialize_tables(tables, orders, marks, answers))
        .map(|_| ())
}

/// 0.8.15 (issue #52): persist 失敗で残った `.tables.tmp` を open 時に明示削除。
/// 通常 persist は `truncate(true)` で上書きするが、 disk full → recovery 後の
/// 状態を確実に clean にするためだけの safety net。 削除失敗は warning だけで続行。
#[cfg(not(target_arch = "wasm32"))]
fn cleanup_tables_tmp(db_path: &str) {
    let sidecar = tables_path_for(db_path);
    let tmp_path = crate::db_files::tmp_path_for(&sidecar);
    if tmp_path.exists() {
        if let Err(e) = std::fs::remove_file(&tmp_path) {
            eprintln!(
                "warning: failed to remove stale tables tmp {}: {}",
                tmp_path.display(),
                e
            );
        }
    }
}

/// 0.8.15 (issue #52): 破損 sidecar を `.tables.corrupt-<unix_ts>` に rename して
/// 退避し、 anonymous fallback で open 続行する。 user 側は schema crate の
/// synthesize 経路で engine 内 table 定義から復元できる。
#[cfg(not(target_arch = "wasm32"))]
fn rename_corrupt_sidecar(db_path: &str, kind: &str, err: &io::Error) {
    use std::time::{SystemTime, UNIX_EPOCH};
    let sidecar = match kind {
        "tables" => tables_path_for(db_path),
        // 将来 schema 用に同 helper を使う場合のため switch (今は tables のみ)
        _ => return,
    };
    let ts = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let backup = crate::db_files::corrupt_backup_path_for(&sidecar, ts);
    eprintln!(
        "warning: {} sidecar parse failed ({}): renaming to {} (anonymous fallback)",
        kind,
        err,
        backup.display()
    );
    if let Err(e) = std::fs::rename(&sidecar, &backup) {
        eprintln!(
            "warning: failed to rename corrupt sidecar {} -> {}: {}",
            sidecar.display(),
            backup.display(),
            e
        );
    }
}

/// β-light step 7: 既存 sidecar を読む。 不在 (v4 DB) なら Ok(None)。 並びの索引の宣言も返す。
#[cfg(not(target_arch = "wasm32"))]
fn load_tables_from_sidecar(db_path: &str) -> io::Result<Option<TablesSidecar>> {
    let sidecar = tables_path_for(db_path);
    enchudb_oplog::io_point("sidecar.read_tables")?;
    match std::fs::read(&sidecar) {
        Ok(buf) => match deserialize_tables(&buf) {
            Ok(t) => Ok(Some(t)),
            Err(e) => Err(io::Error::new(io::ErrorKind::InvalidData, e)),
        },
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e),
    }
}


/// #9: eid 翻訳テーブルの sidecar path。 `.eidmap`。 中身は
/// `(author_peer, foreign_local, local)` の binary 配列。 不在 (= sync してない DB
/// や旧 DB) なら open 時に空の translator で続行 (additive、 後方互換)。
#[cfg(not(target_arch = "wasm32"))]
fn eidmap_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::EIDMAP)
}

/// #9: eidmap sidecar の 1 entry。 `(author_peer, foreign_local, local, tombstone_hlc)`。
/// `tombstone_hlc == Hlc::ZERO` は「削除されていない」。 v2 (0.8.19) で tombstone を追加し、
/// reopen 後の削除済み entity 復活 (resurrection) を防ぐ。
type EidmapEntry = (enchudb_oplog::PeerId, u32, u32, enchudb_oplog::Hlc);

/// #9: 翻訳 entry を binary encode (v2)。
/// layout: magic "EIDM"(4) + version u32=2 + count u32
///         + (peer u32, foreign u32, local u32, tomb_wall u64, tomb_logical u32, tomb_peer u32) × count
/// #166: `.eidmap` の現行 format 版数。
///
/// - v1: tombstone 無し (12 byte/entry)
/// - v2: tombstone 込み (28 byte/entry)
/// - v3: v2 と **同じ 28 byte/entry**。 `local == NO_LOCAL_SLOT` の entry が
///   「slot を持たない削除記録」 を意味するようになった (`foreign_tombs` の永続化)
///
/// 読み手は 3 版すべてを読める。 v3 を v2 の reader に食わせると
/// `NO_LOCAL_SLOT` を実在 slot として扱ってしまうので版数を上げてある
/// (v9 DB は FILE_VERSION 側で旧 binary を弾くため実害は無いが、 format の
/// 自己記述性として正しい形にしておく)。
const EIDMAP_VERSION: u32 = 3;

/// #166: 「この entry は写像ではなく削除記録だけ」 を表す番兵。
/// `max_entities` は `u32::MAX` 未満なので実在 slot と衝突しない。
const NO_LOCAL_SLOT: u32 = u32::MAX;

/// #268: bridge の無言停止を 1 行警告するまでの連続空 scan 数。
const BRIDGE_STALL_WARN_AFTER: u64 = 256;

/// #268: 同じく、 警告までに episode が続いていなければならない実時間 (ms)。
///
/// **回数だけでは足りない**。 head は record 本体の書き込み **前** に bump されるので、
/// 書き込み途中の batch を見ている間は 「head > cursor かつ空 scan」 が正常に起きる。
/// commit は consumer thread の fsync 周期 (100 ms) で付く。 つまり異常かどうかは
/// **経過時間**の問題で、 scan を何回回したかではない — host が tight loop で
/// `transfer_oplog_to_sync_ops()` を叩けば、 正常な batch の途中でも 256 回は 1 秒未満で
/// 埋まる (`bridge_counters_separate_a_quiet_bridge_from_a_stalled_one` で実際に踏んだ)。
/// 実機の事象は 41 時間なので、 30 秒の下限で見落とすことはない。
const BRIDGE_STALL_WARN_AFTER_MS: u64 = 30_000;

/// #57: WAL が満杯で落ち続けていても、 最初に落ちてからこれだけ経ったら history floor を上げる (ms)。
/// 満杯が終わった周にはすぐ上げる。
const WAL_DROP_FLOOR_MAX_DELAY_MS: u64 = 5_000;

/// #57 / #391: 最後に落ちてからこれだけ新しく落ちなかったら、 満杯の episode は終わった (ms、 consumer の書き出しの
/// 周期)。 「前に bridge が見た時から落ちていない」 で決めると、 bridge を見る間隔で答えが変わる — 満杯を待つ書き手が
/// consumer を起こして bridge を回すと、 落ちと落ちの間に毎回 「終わった」 になり floor を上げ続けた。
const WAL_DROP_EPISODE_QUIET_MS: u64 = 100;

/// #451 (段階 1): 配り済みの印の候補 = 切れ目 (`Engine::take_durable_cut`)。 置く時 (`Engine::end_durable_cut`) に S を決める。
struct DurableCut {
    hlc: enchudb_oplog::Hlc,
    /// 切れ目の前に読んだ `next_sync_lsn - 1` (S の下限: ここまでの行は切れ目より前)
    lsn_at_cut: u32,
    /// oplog の (周, 切れ目の時の終わり): 開く時の header の走査はここから
    wal: (u32, u64),
    /// 切れ目の時の、 自分の落ちた record を覚えた回数 (`OpLog::dropped_gen`)。 置く時に変わっていれば置かない (切れ目の後の Commit が
    /// 満杯で畳みを起こし、 切れ目以下の閉じていない record を孤児 (#450) として落とした時: 時計では分からない)
    dropped_gen: u64,
}

fn serialize_eidmap(entries: &[EidmapEntry]) -> Vec<u8> {
    let mut out = Vec::with_capacity(12 + entries.len() * 28);
    out.extend_from_slice(b"EIDM");
    out.extend_from_slice(&EIDMAP_VERSION.to_le_bytes());
    out.extend_from_slice(&(entries.len() as u32).to_le_bytes());
    for &(peer, foreign_local, local, tomb) in entries {
        out.extend_from_slice(&peer.to_le_bytes());
        out.extend_from_slice(&foreign_local.to_le_bytes());
        out.extend_from_slice(&local.to_le_bytes());
        out.extend_from_slice(&tomb.wall.to_le_bytes());
        out.extend_from_slice(&tomb.logical.to_le_bytes());
        out.extend_from_slice(&tomb.peer.to_le_bytes());
    }
    out
}

/// #9: eidmap sidecar を decode。 magic 不一致 / truncated は Err。 v1 (tombstone 無し、
/// 12 byte/entry) と v2 (tombstone 込み、 28 byte/entry) の両方を読める。
fn deserialize_eidmap(buf: &[u8]) -> Result<Vec<EidmapEntry>, String> {
    if buf.len() < 12 || &buf[0..4] != b"EIDM" {
        return Err("eidmap sidecar: bad magic".into());
    }
    let version = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    let entry_size = match version {
        1 => 12usize,
        // v2 と v3 は同じ長さ。 違いは `local == NO_LOCAL_SLOT` の解釈だけで、
        // その判定は読み手 (`load` 側) が行う。
        2 | 3 => 28usize,
        v => return Err(format!("eidmap sidecar: unsupported version {}", v)),
    };
    let count = u32::from_le_bytes(buf[8..12].try_into().unwrap()) as usize;
    // 破損 / torn header ガード: `count` は信用しない。 各 entry は固定長なので上限は
    // 残りバッファで決まる。 bogus な巨大 count をそのまま with_capacity に渡すと数 GB の
    // 確保要求で open 時に abort する (.eidmap は CRC 無し)。 上限超過は破損とみなし Err
    // → load_eidmap_from_sidecar 側で空 translator に graceful fallback。
    let max_entries = (buf.len() - 12) / entry_size;
    if count > max_entries {
        return Err(format!(
            "eidmap sidecar: count {} exceeds buffer capacity {} (corrupt/torn)",
            count, max_entries
        ));
    }
    let mut entries = Vec::with_capacity(count);
    let mut off = 12usize;
    for _ in 0..count {
        if off + entry_size > buf.len() {
            return Err("eidmap sidecar: truncated".into());
        }
        let peer = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
        let foreign_local = u32::from_le_bytes(buf[off + 4..off + 8].try_into().unwrap());
        let local = u32::from_le_bytes(buf[off + 8..off + 12].try_into().unwrap());
        let tomb = if entry_size == 28 {
            let wall = u64::from_le_bytes(buf[off + 12..off + 20].try_into().unwrap());
            let logical = u32::from_le_bytes(buf[off + 20..off + 24].try_into().unwrap());
            let tpeer = u32::from_le_bytes(buf[off + 24..off + 28].try_into().unwrap());
            enchudb_oplog::Hlc { wall, logical, peer: tpeer }
        } else {
            enchudb_oplog::Hlc::ZERO
        };
        off += entry_size;
        entries.push((peer, foreign_local, local, tomb));
    }
    Ok(entries)
}

/// #560: `eidmap` の bytes と、 その続きの `eidmap.log` の record (log が無い / 合わなければ None、 (record, 切れていたか)) を読む。
/// 不在なら Ok(None)。 log を先に読む: まとめ直しは `eidmap` → 空の log の順に置き換えるので、 log の後に読んだ `eidmap` が合わ
/// なければ、 その `eidmap` は log より新しい = 全部を持つ (別の process の書き手と並ぶ読み手 (readonly で開く / relay の bootstrap)
/// でも、 log にだけある写像を落とさない)。 逆の順だと、 2 つを読む間にまとめ直しが入れば古い `eidmap` だけが残る。
#[cfg(not(target_arch = "wasm32"))]
#[allow(clippy::type_complexity)]
fn read_eidmap_sidecars(db_path: &str) -> io::Result<Option<(Vec<u8>, Option<(Vec<crate::eidmap_log::Entry>, bool)>)>> {
    enchudb_oplog::io_point("sidecar.read_eidmap")?;
    let log = match std::fs::read(crate::db_files::path_for(db_path, crate::db_files::EIDMAP_LOG)) {
        Ok(log) => Some(log),
        Err(e) if e.kind() == io::ErrorKind::NotFound => None,
        Err(e) => return Err(e),
    };
    #[cfg(test)]
    eidmap_read_hook::between_reads();
    let buf = match std::fs::read(eidmap_path_for(db_path)) {
        Ok(buf) => buf,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(e) => return Err(e),
    };
    let records = log.and_then(|log| crate::eidmap_log::read(&log, &buf));
    Ok(Some((buf, records)))
}

/// 試験用: `read_eidmap_sidecars` の 2 つの読みの間で走らせる処理 (読む間にまとめ直しが入った形を必ず作る)。
#[cfg(test)]
mod eidmap_read_hook {
    use std::cell::RefCell;
    thread_local! {
        static HOOK: RefCell<Option<Box<dyn FnOnce()>>> = const { RefCell::new(None) };
    }
    pub(super) fn set(f: impl FnOnce() + 'static) {
        HOOK.with(|h| *h.borrow_mut() = Some(Box::new(f)));
    }
    pub(super) fn between_reads() {
        if let Some(f) = HOOK.with(|h| h.borrow_mut().take()) {
            f();
        }
    }
}

/// #9: eidmap sidecar を読む。 不在なら Ok(None)。 #560: 続きの `eidmap.log` があれば当て、 log の様子も返す (log が無い / 合わない /
/// 切れていれば、 次の書き出しでまとめ直す)。
#[cfg(not(target_arch = "wasm32"))]
fn load_eidmap_from_sidecar(db_path: &str) -> io::Result<Option<(Vec<EidmapEntry>, crate::eidmap_log::LogState)>> {
    let Some((buf, log)) = read_eidmap_sidecars(db_path)? else {
        return Ok(None);
    };
    let entries = deserialize_eidmap(&buf).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    Ok(Some(match log {
        Some((records, torn)) => {
            let state = crate::eidmap_log::LogState { records: records.len() as u64, ok: !torn };
            (crate::eidmap_log::merge(entries, &records), state)
        }
        None => (entries, crate::eidmap_log::LogState::default()),
    }))
}

/// #178: 翻訳の別名の sidecar path (`eidalias`)。 不在 = 別名なし。
#[cfg(not(target_arch = "wasm32"))]
fn eidalias_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::EIDALIAS)
}

/// #178: 別名 (`(author_peer, foreign_local, local)`) を binary encode。
/// layout: magic "EIDA"(4) + version u32=1 + count u32 + (peer u32, foreign u32, local u32) × count
fn serialize_eidalias(entries: &[(enchudb_oplog::PeerId, u32, u32)]) -> Vec<u8> {
    let mut out = Vec::with_capacity(12 + entries.len() * 12);
    out.extend_from_slice(b"EIDA");
    out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&(entries.len() as u32).to_le_bytes());
    for &(peer, foreign_local, local) in entries {
        out.extend_from_slice(&peer.to_le_bytes());
        out.extend_from_slice(&foreign_local.to_le_bytes());
        out.extend_from_slice(&local.to_le_bytes());
    }
    out
}

/// #178: `serialize_eidalias` の逆。 magic / 版の不一致・切れた中身は Err (件数は残りの長さで頭打ち、 `.eidmap` と同じ)。
fn deserialize_eidalias(buf: &[u8]) -> Result<Vec<(enchudb_oplog::PeerId, u32, u32)>, String> {
    if buf.len() < 12 || &buf[0..4] != b"EIDA" {
        return Err("eidalias sidecar: bad magic".into());
    }
    let version = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    if version != 1 {
        return Err(format!("eidalias sidecar: unsupported version {version}"));
    }
    let count = u32::from_le_bytes(buf[8..12].try_into().unwrap()) as usize;
    if count != (buf.len() - 12) / 12 || (buf.len() - 12) % 12 != 0 {
        return Err(format!("eidalias sidecar: count {count} does not match {} bytes (corrupt/torn)", buf.len()));
    }
    let rd = |o: usize| u32::from_le_bytes(buf[o..o + 4].try_into().unwrap());
    Ok((0..count).map(|i| 12 + i * 12).map(|o| (rd(o), rd(o + 4), rd(o + 8))).collect())
}

/// #178: 別名を sidecar に atomic 書き換え。 別名が無ければ file を消す (残すと、 畳んだ行の slot が回った後で開き直した
/// 時に古い別名が戻り、 別名宛ての record が無関係な行に入る)。
#[cfg(not(target_arch = "wasm32"))]
fn persist_eidalias_to_sidecar(db_path: &str, entries: &[(enchudb_oplog::PeerId, u32, u32)]) -> io::Result<()> {
    let p = eidalias_path_for(db_path);
    if entries.is_empty() {
        return match std::fs::remove_file(&p) {
            Err(e) if e.kind() != io::ErrorKind::NotFound => Err(e),
            _ => Ok(()),
        };
    }
    crate::db_files::write_atomic_if_changed(&p, &serialize_eidalias(entries)).map(|_| ())
}

/// #178: 別名の sidecar を読む。 不在なら Ok(None)。
#[cfg(not(target_arch = "wasm32"))]
fn load_eidalias_from_sidecar(db_path: &str) -> io::Result<Option<Vec<(enchudb_oplog::PeerId, u32, u32)>>> {
    enchudb_oplog::io_point("sidecar.read_eidalias")?;
    match std::fs::read(eidalias_path_for(db_path)) {
        Ok(buf) => deserialize_eidalias(&buf).map(Some).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e),
    }
}

/// #513: 消した主キーの記録の sidecar path (`pktombs`、 中身は `pk_tombs.rs`)。 不在 (主キーのある行を sync の DB で
