/// **peer vocab 写像の sidecar path**。 `.vocabmap`。
///
/// text (Tag/Leaf) の cell 値は `(author_peer, remote_vid) → local_vid` の写像を
/// 通してしか意味を持たない。 この写像は受信した `Vocab` op から組み立てるが、
/// **受信 op は自分の WAL には残らない** (gossip_remote_apply が off なら
/// append_relayed も走らない) ため、 memory から消えると復元手段が無い。
///
/// `(peer, remote_eid) → local` を持つ `.eidmap` と同格の永続先がここ。 両方
/// 揃って初めて「pull cursor が消費した state」が disk 上で再構成できる。
#[cfg(not(target_arch = "wasm32"))]
fn vocabmap_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::VOCABMAP)
}

/// vocabmap sidecar の 1 entry。 `(author_peer, remote_vid, local_vid)`。
type VocabmapEntry = (enchudb_oplog::PeerId, u32, u32);

/// `.vocabmap` の現行 format 版数。
///
/// - v1: magic "EVCM"(4) + version u32 + count u32 + (peer u32, remote u32, local u32) × count
const VOCABMAP_VERSION: u32 = 1;

/// vocabmap entry を binary encode (v1)。
fn serialize_vocabmap(entries: &[VocabmapEntry]) -> Vec<u8> {
    let mut out = Vec::with_capacity(12 + entries.len() * 12);
    out.extend_from_slice(b"EVCM");
    out.extend_from_slice(&VOCABMAP_VERSION.to_le_bytes());
    out.extend_from_slice(&(entries.len() as u32).to_le_bytes());
    for &(peer, remote_vid, local_vid) in entries {
        out.extend_from_slice(&peer.to_le_bytes());
        out.extend_from_slice(&remote_vid.to_le_bytes());
        out.extend_from_slice(&local_vid.to_le_bytes());
    }
    out
}

/// vocabmap sidecar を decode。 magic 不一致 / truncated は Err。
///
/// `.eidmap` と同じく CRC を持たないので、 header の `count` は信用せず
/// 残りバッファから上限を出す (bogus な巨大 count での確保 abort を防ぐ)。
fn deserialize_vocabmap(buf: &[u8]) -> Result<Vec<VocabmapEntry>, String> {
    if buf.len() < 12 || &buf[0..4] != b"EVCM" {
        return Err("vocabmap sidecar: bad magic".into());
    }
    let version = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    if version != VOCABMAP_VERSION {
        return Err(format!("vocabmap sidecar: unsupported version {}", version));
    }
    const ENTRY_SIZE: usize = 12;
    let count = u32::from_le_bytes(buf[8..12].try_into().unwrap()) as usize;
    let max_entries = (buf.len() - 12) / ENTRY_SIZE;
    if count > max_entries {
        return Err(format!(
            "vocabmap sidecar: count {} exceeds buffer capacity {} (corrupt/torn)",
            count, max_entries
        ));
    }
    let mut entries = Vec::with_capacity(count);
    let mut off = 12usize;
    for _ in 0..count {
        if off + ENTRY_SIZE > buf.len() {
            return Err("vocabmap sidecar: truncated".into());
        }
        let peer = u32::from_le_bytes(buf[off..off + 4].try_into().unwrap());
        let remote_vid = u32::from_le_bytes(buf[off + 4..off + 8].try_into().unwrap());
        let local_vid = u32::from_le_bytes(buf[off + 8..off + 12].try_into().unwrap());
        off += ENTRY_SIZE;
        entries.push((peer, remote_vid, local_vid));
    }
    Ok(entries)
}

/// vocabmap を sidecar に atomic 書き換え (fsync 込み)。 entries 空なら何もしない
/// (= sync してない DB に空ファイルを作らない)。
#[cfg(not(target_arch = "wasm32"))]
fn persist_vocabmap_to_sidecar(db_path: &str, entries: &[VocabmapEntry]) -> io::Result<()> {
    if entries.is_empty() {
        return Ok(());
    }
    crate::db_files::write_atomic_if_changed(&vocabmap_path_for(db_path), &serialize_vocabmap(entries))
        .map(|_| ())
}

/// vocabmap sidecar を読む。 不在なら Ok(None)。
#[cfg(not(target_arch = "wasm32"))]
fn load_vocabmap_from_sidecar(db_path: &str) -> io::Result<Option<Vec<VocabmapEntry>>> {
    enchudb_oplog::io_point("sidecar.read_vocabmap")?;
    match std::fs::read(vocabmap_path_for(db_path)) {
        Ok(buf) => match deserialize_vocabmap(&buf) {
            Ok(entries) => Ok(Some(entries)),
            Err(e) => Err(io::Error::new(io::ErrorKind::InvalidData, e)),
        },
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(e),
    }
}

/// writer 排他用 sidecar の path (v10: `{db}/lock`)。
#[cfg(not(target_arch = "wasm32"))]
fn writer_lock_path_for(path: &str) -> std::path::PathBuf {
    crate::db_files::path_for(path, crate::db_files::LOCK)
}

/// 同一プロセス内で writer lock を保持中の lock path の registry (#80)。
/// flock は open file description 単位なので、同一プロセスからの二重 open は
/// block 検知できず無期限ハングになる。flock に入る前にここで fast-fail する。
#[cfg(not(target_arch = "wasm32"))]
static WRITER_LOCK_REGISTRY: std::sync::LazyLock<
    std::sync::Mutex<std::collections::HashSet<std::path::PathBuf>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::HashSet::new()));

#[cfg(not(target_arch = "wasm32"))]
fn writer_registry() -> std::sync::MutexGuard<'static, std::collections::HashSet<std::path::PathBuf>>
{
    WRITER_LOCK_REGISTRY
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
}

/// writer lock の保持を表す guard。 drop で registry から抜け、 fd close で
/// flock も解放される。
#[cfg(not(target_arch = "wasm32"))]
pub(crate) struct WriterLock {
    _file: std::fs::File,
    key: std::path::PathBuf,
    /// 別 process を排他できているか (false = advisory lock を持たない FS で、 排他なしで続けている)
    exclusive: bool,
}

/// `open_immutable` の 「書き手は居ない」 という宣言を debug build で確かめるための、 writer lock の file (#395)。
/// lock は持たない (書き手を待たせない)。 借用の読みのたびに、 誰かが排他を持っていないかを見るだけ。
#[cfg(not(target_arch = "wasm32"))]
#[cfg_attr(not(debug_assertions), allow(dead_code))]
pub(crate) struct ImmutableWatch {
    lock_path: std::path::PathBuf,
    /// 読み取りだけで開いた lock file。 開いた時に無ければ None (書き手が開けば作られるので、 見るたびに開き直す)。
    file: std::sync::Mutex<Option<std::fs::File>>,
}

#[cfg(not(target_arch = "wasm32"))]
impl ImmutableWatch {
    fn new(path: &str) -> io::Result<Self> {
        let lock_path = writer_lock_path_for(path);
        let w = Self { lock_path, file: std::sync::Mutex::new(None) };
        if w.writer_present()? == Some(true) {
            return Err(io::Error::new(
                io::ErrorKind::WouldBlock,
                format!(
                    "\"{path}\" is open for writing in another Engine; open_immutable requires that no writer \
                     exists (use open_readonly to read alongside a writer)"
                ),
            ));
        }
        Ok(w)
    }

    /// 今、 書き手 (writer lock の排他) が居るか。 `None` = lock を持たない FS / lock file が無い (= 書き手が
    /// 1 度も開いていない) で分からない or 居ない。
    fn writer_present(&self) -> io::Result<Option<bool>> {
        let mut file = self.file.lock().unwrap_or_else(|p| p.into_inner());
        if file.is_none() {
            match std::fs::File::open(&self.lock_path) {
                Ok(f) => *file = Some(f),
                Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(None),
                Err(e) => return Err(e),
            }
        }
        enchudb_oplog::filelock::exclusive_held(file.as_ref().expect("opened above"))
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl Drop for WriterLock {
    fn drop(&mut self) {
        writer_registry().remove(&self.key);
        // `_file` はこの後 drop され、 close で flock が解放される。
        // registry 解除 → close の順なので、 競合した同一プロセスの open は
        // fast-fail ではなく一瞬 flock で待ってから取得する (spurious error なし)。
    }
}

/// `.db.lock` に flock(LOCK_EX) を取り、 guard を返す。 guard が drop されると
/// lock も解放。 **別プロセス**が保持中は block する (= sqlite と同様、 取れる
/// まで待つ)。 **同一プロセス**が既に保持中は block せず即エラー (#80、
/// `ErrorKind::WouldBlock`)。 readonly open は呼ばない。 writer 系の
/// open だけ呼ぶ (create は [`try_acquire_writer_lock`])。
#[cfg(not(target_arch = "wasm32"))]
fn acquire_writer_lock(path: &str) -> io::Result<WriterLock> {
    Ok(lock_writer(path, true)?.expect("待つ lock は取れるまで返らない"))
}

/// #437: create 用の writer lock。 別の handle (別 process / 同じ process の Engine) が持っていれば、 少しの間 (約 20 ms)
/// 取り直して、 それでも取れなければ `Ok(None)`。 同時の open (header が無いのですぐ離す) や、 別の thread が起動した子
/// process が exec までに持つ fd の写しはすぐ離すので待つ。 作り始めた create / 開いている Engine は離さないので、 待ち
/// 切らずに諦める (0.31.1 までの create は lock を待ち続けた)。
#[cfg(not(target_arch = "wasm32"))]
fn try_acquire_writer_lock(path: &str) -> io::Result<Option<WriterLock>> {
    for _ in 0..20 {
        if let Some(lock) = lock_writer(path, false)? {
            return Ok(Some(lock));
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
    }
    lock_writer(path, false)
}

#[cfg(not(target_arch = "wasm32"))]
fn lock_writer(path: &str, wait: bool) -> io::Result<Option<WriterLock>> {
    // v10: lock は DB directory の中。 directory は create 側が作り、 open は存在を
    // `check_db_dir` で確認済み (無い path に空 directory を残さない)。
    let lock_path = writer_lock_path_for(path);
    enchudb_oplog::io_point("lock.open")?;
    let f = OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(false)
        .open(&lock_path)?;
    #[cfg(test)]
    AFTER_LOCK_FILE_OPEN.with(|h| {
        if let Some(h) = h.borrow().as_ref() {
            h()
        }
    });
    // 直前に create 済みなので canonicalize は通常成功する (symlink / 相対 path
    // の表記揺れで registry をすり抜けないための正規化)。
    let key = lock_path.canonicalize().unwrap_or(lock_path);
    if !writer_registry().insert(key.clone()) {
        if !wait {
            return Ok(None);
        }
        return Err(io::Error::new(
            io::ErrorKind::WouldBlock,
            format!(
                "\"{path}\" is already open for writing in this process \
                 (drop the existing Engine handle first, or use open_readonly)"
            ),
        ));
    }
    // std::fs::File::lock (Rust 1.89 安定化) は unix で flock、 Windows で
    // LockFileEx に落ちる。 ただし std は対応 target を列挙で持っており、
    // **Android (bionic) は `Unsupported`** を返す ("lock() not supported")。
    // #280: その穴は `enchudb_oplog::filelock` が libc の flock で塞ぐ
    // (WAL の append guard と同じ経路 = 意味論を 1 箇所に揃える)。
    let got = enchudb_oplog::io_point("lock.flock").and_then(|()| {
        if wait {
            enchudb_oplog::filelock::lock_exclusive(&f).map(Some)
        } else {
            enchudb_oplog::filelock::try_lock_exclusive_outcome(&f)
        }
    });
    let exclusive = match got {
        Ok(Some(enchudb_oplog::filelock::LockOutcome::Locked)) => true,
        // advisory lock を持たない FS (一部の FUSE / ネットワーク FS) では
        // **プロセス間の排他を諦めて続行する**。 同一プロセスの二重 open は上の
        // registry が止めるので、 1 app = 1 process の構成は安全側に倒れる。
        // ここで落とすと platform / FS ごと使えなくなるため、 警告 1 回で開ける。
        Ok(Some(enchudb_oplog::filelock::LockOutcome::Unsupported)) => {
            static WARNED: std::sync::atomic::AtomicBool =
                std::sync::atomic::AtomicBool::new(false);
            if !WARNED.swap(true, std::sync::atomic::Ordering::Relaxed) {
                eprintln!(
                    "[enchudb] warning: this filesystem has no advisory locks — opening \
                     \"{path}\" WITHOUT cross-process writer exclusion. a second process \
                     writing the same DB will corrupt it."
                );
            }
            false
        }
        // 待たない時だけ: 別 process が持っている
        Ok(None) => {
            writer_registry().remove(&key);
            return Ok(None);
        }
        Err(err) => {
            writer_registry().remove(&key);
            return Err(err);
        }
    };
    Ok(Some(WriterLock { _file: f, key, exclusive }))
}

/// #437: 取った writer lock が今の `{path}/lock` か。 lock を取るまでの間に、 失敗した create が directory ごと消して
/// いれば (lock file を開いた後に消された)、 消えた file の lock を取っている。
#[cfg(unix)]
fn lock_is_current(lock: &WriterLock, path: &str) -> bool {
    use std::os::unix::fs::MetadataExt;
    match (lock._file.metadata(), std::fs::metadata(writer_lock_path_for(path))) {
        (Ok(held), Ok(now)) => held.dev() == now.dev() && held.ino() == now.ino(),
        _ => false,
    }
}

/// unix 以外は file の同一性を std で見られない。 開いている file は消せない (Windows) ので、 在ることだけ見る。
#[cfg(all(not(unix), not(target_arch = "wasm32")))]
fn lock_is_current(_lock: &WriterLock, path: &str) -> bool {
    writer_lock_path_for(path).exists()
}

/// 0.9.0 (H11): create 系 API の既存ファイルガード。
/// 旧実装は `create(true).truncate(true)` で **既存 DB を無警告で 0 バイトに破壊**
/// していた (typo った path を create しただけで全損)。 FFI 契約
/// (`enchudb_create`: 「既存ファイルがあると Engine 側でエラー」) 通り、
/// 存在する path への create は `AlreadyExists` で拒否する。
/// 既存 DB を開くなら `Engine::open*`、 作り直すなら caller が明示的に削除すること。
#[cfg(not(target_arch = "wasm32"))]
/// v10: DB directory を作り、 writer lock を持って返す。 `mkdir` の atomic 性で「既存を silent に潰さない」 (H11)。
/// 既存が file でも、 DB / DB でない directory でも `AlreadyExists`。 前の create が途中で落ちた残骸
/// ([`is_create_remnant`]) なら、 その場で作り直す。
///
/// #437: lock は作り始める前に取る (待たない)。 取れない = 別の create が作っている / 作り終えて使っている ので
/// `AlreadyExists` (同時 create は片方だけ勝つ)。 残骸は消さずに、 lock を持ったまま中身を片付けて使う。 旧 (#415):
/// 作成中の印を置いて fsync してから lock を取っていたので、 その間の directory を同時の create が残骸と見て消して
/// 作り直し、 消された側がその directory の lock を先に取って作り終えると、 lock を待っていた側が後から
/// (`SegmentSet::create` の `AlreadyExists` の片付けで) 作り終えた DB を消した。
#[cfg(not(target_arch = "wasm32"))]
fn create_db_dir(path: &str) -> io::Result<WriterLock> {
    let dir = std::path::Path::new(path);
    let exists = || {
        io::Error::new(
            io::ErrorKind::AlreadyExists,
            format!(
                "database already exists: \"{path}\" — refusing to overwrite. \
                 use Engine::open* to open the existing DB, or remove it first"
            ),
        )
    };
    let made = match enchudb_oplog::io_point("create.mkdir").and_then(|()| std::fs::create_dir(dir)) {
        Ok(()) => true,
        // #323 / #415: 前の create が途中で落ちた残骸。 作成中の create もこの形に見えるので、 下の lock で分ける
        Err(e) if e.kind() == io::ErrorKind::AlreadyExists && is_create_remnant(dir) => false,
        Err(e) if e.kind() == io::ErrorKind::AlreadyExists => return Err(exists()),
        Err(e) => return Err(e),
    };
    #[cfg(test)]
    BEFORE_CREATE_LOCK.with(|h| {
        if let Some(h) = h.borrow().as_ref() {
            h()
        }
    });
    // 取れなければ、 別の create が作っている (または作り終えて使っている)。 何も書いていないので片付けない
    let Some(lock) = try_acquire_writer_lock(path)? else {
        return Err(exists());
    };
    // lock を取るまでの間に、 別の create がここを作り終えた / 失敗して消した。 lock を持たない FS では、 作成中の
    // create と落ちた残骸を分けられないので、 自分で作った directory しか使わない
    if !lock_is_current(&lock, path) || !is_create_remnant(dir) || (!made && !lock.exclusive) {
        return Err(exists());
    }
    // #415: 作成中の印。 作った中身を全部書き出してから消す (`Engine::finish_create`)。 印より先に directory の
    // 中身が届くことの無いよう、 印を書き出してから先へ進む。 前の create の残りは印の後に消す (消す途中で落ちても、
    // 印のある残骸のまま)
    let marker = dir.join(crate::db_files::CREATING);
    let started = enchudb_oplog::io_point("create.marker").and_then(|()| std::fs::File::create(&marker)).and_then(|f| f.sync_all()).and_then(|()| {
        sync_dir(dir);
        if let Some(parent) = dir.parent() {
            sync_dir(parent);
        }
        clear_create_remnant(dir)
    });
    if let Err(e) = started {
        abandon_create(path, lock);
        return Err(e);
    }
    Ok(lock)
}

/// #437: 前の create が残した中身 (lock と作成中の印以外) を消す。 lock を持って、 印を書き出した後に呼ぶ。
#[cfg(not(target_arch = "wasm32"))]
fn clear_create_remnant(dir: &std::path::Path) -> io::Result<()> {
    for ent in std::fs::read_dir(dir)? {
        let ent = ent?;
        let name = ent.file_name();
        if name == crate::db_files::LOCK || name == crate::db_files::CREATING {
            continue;
        }
        if ent.file_type()?.is_dir() {
            std::fs::remove_dir_all(ent.path())?;
        } else {
            std::fs::remove_file(ent.path())?;
        }
    }
    Ok(())
}

/// #323: 失敗した create の directory を消す。 #437: lock を持っている時だけ呼ぶ (持たずに消すと、 別の create が
/// 作っている directory を消す)。 unix は lock を持ったまま消す (開いている lock file も消せる) ので、 消している最中の
/// directory に同時の create が入り込まない (lock を取った後に [`lock_is_current`] で気づく)。
#[cfg(not(target_arch = "wasm32"))]
fn abandon_create(path: &str, lock: WriterLock) {
    #[cfg(unix)]
    {
        let _ = std::fs::remove_dir_all(path);
        drop(lock);
    }
    #[cfg(not(unix))]
    {
        // Windows は開いている file を消せない
        drop(lock);
        let _ = std::fs::remove_dir_all(path);
    }
}

/// #415: directory の entry (作った / 消した file) を書き出す。 失敗は無視する (directory の fsync を持たない FS がある)。
#[cfg(not(target_arch = "wasm32"))]
fn sync_dir(dir: &std::path::Path) {
    let dir = if dir.as_os_str().is_empty() { std::path::Path::new(".") } else { dir };
    if let Ok(d) = std::fs::File::open(dir) {
        let _ = d.sync_all();
    }
}

/// #419 の試験用 (crashsim feature): 本体の書き出し (`write_out_body`) を段の切れ目で止める hook。 電源断の
/// 模擬で、 並行の書き手が書く時機を決めて撮るのに使う (`tests/power_loss.rs`)。
#[cfg(feature = "crashsim")]
#[doc(hidden)]
pub mod write_out_hook {
    use std::sync::{Arc, Mutex};

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum Phase {
        /// 中身の segment を書き出した後 (門を閉じる前)
        BeforeGate,
        /// 門を閉じた直後 (中身をもう一度書き出す前)
        Closed,
        /// 門を閉じて中身をもう一度書き出した後 (中身を指す列を書き出す前)
        GateClosed,
        /// 中身を指す列を書き出して門を開いた後 (残りを書き出す前)
        Opened,
    }

    type Hook = Arc<dyn Fn(Phase) + Send + Sync>;
    static HOOK: Mutex<Option<Hook>> = Mutex::new(None);

    pub fn set(hook: Option<Hook>) {
        *HOOK.lock().unwrap_or_else(|p| p.into_inner()) = hook;
    }

    pub(crate) fn call(phase: Phase) {
        let hook = HOOK.lock().unwrap_or_else(|p| p.into_inner()).clone();
        if let Some(h) = hook {
            h(phase);
        }
    }
}

/// test 用の WAL の割り込み点の置き場 (#579)。 WAL (番地で見分ける) ごとに 1 つ置き、 置いた WAL で 1 回だけ呼ぶ。 前は process に
/// 置き場が 1 つで、 同じ割り込み点を使う試験が並んで走ると、 後に置いた試験が先の試験の割り込み点を消した。
#[cfg(test)]
mod wal_hook {
    use enchudb_oplog::oplog::OpLog;
    use std::sync::Mutex;

    type Hook = Box<dyn FnOnce(&OpLog) + Send>;

    pub(super) struct Slots(Mutex<Vec<(usize, Hook)>>);

    impl Slots {
        pub(super) const fn new() -> Self {
            Slots(Mutex::new(Vec::new()))
        }

        /// WAL `wal` の割り込み点を `f` にする (その WAL に置いた前の物は置き換える)。
        pub(super) fn set(&self, wal: &OpLog, f: impl FnOnce(&OpLog) + Send + 'static) {
            let at = wal as *const OpLog as usize;
            let mut v = self.0.lock().unwrap_or_else(|p| p.into_inner());
            v.retain(|(w, _)| *w != at);
            v.push((at, Box::new(f)));
        }

        /// WAL `wal` に置いた割り込み点があれば取り出して呼ぶ。
        pub(super) fn call(&self, wal: &OpLog) {
            let me = wal as *const OpLog as usize;
            let hit = {
                let mut v = self.0.lock().unwrap_or_else(|p| p.into_inner());
                v.iter().position(|(w, _)| *w == me).map(|i| v.swap_remove(i))
            };
            if let Some((_, f)) = hit {
                f(wal);
            }
        }
    }
}

/// test 用: 置いた WAL の書き出し (`sync_for_checkpoint`) を失敗させる (#554: sync の表の無い DB で満杯の WAL を畳めない形)。
#[cfg(test)]
mod write_out_fault {
    use enchudb_oplog::oplog::OpLog;
    use std::sync::Mutex;

    static ON: Mutex<Vec<usize>> = Mutex::new(Vec::new());

    pub(super) fn set(wal: &OpLog, on: bool) {
        let at = wal as *const OpLog as usize;
        let mut v = ON.lock().unwrap_or_else(|p| p.into_inner());
        v.retain(|w| *w != at);
        if on {
            v.push(at);
        }
    }

    pub(super) fn active(wal: &OpLog) -> bool {
        ON.lock().unwrap_or_else(|p| p.into_inner()).contains(&(wal as *const OpLog as usize))
    }
}

